import Foundation

/// The catalog ID for the basic catalog.
/// Mirrors Flutter's `basicCatalogId` from `primitives/constants.dart` and v0.9
/// spec examples (`createSurface.catalogId`).
public let basicCatalogId =
    "https://a2ui.org/specification/v0_9/basic_catalog.json"

/// The ready-to-use Basic Catalog instance.
///
/// Contains all 18 standard components and 25 built-in functions.
/// Pass this to `SurfaceViewModel`, `MessageProcessor`, or `A2UISurfaceView`.
///
/// Mirrors the React renderer's `basicCatalog` singleton in
/// `renderers/react/src/v0_9/catalog/basic/index.ts`.
///
/// # Usage
/// ```swift
/// let vm = SurfaceViewModel(catalog: basicCatalog)
/// try vm.processMessages(messages)
/// A2UISurfaceView(viewModel: vm)
/// ```
public nonisolated(unsafe) let basicCatalog = Catalog(
    id: basicCatalogId,
    componentNames: BASIC_COMPONENT_NAMES,
    functions: BASIC_FUNCTIONS
----
    /// Processes a batch of server-to-client messages.
    /// Per spec §76-82: if one message fails, logs the error and continues with the rest.
    /// Returns any errors that occurred during processing (empty if all succeeded).
    @discardableResult
    public func processMessages(_ messages: [A2uiMessage]) -> [Error] {
        var errors: [Error] = []
        for message in messages {
            do {
                try processMessage(message)
            } catch {
                errors.append(error)
            }
        }
        return errors
    }

    public func processMessage(_ message: A2uiMessage) throws {
        switch message {
        case .createSurface(let payload):
            handleCreateSurface(payload)
        case .updateComponents(let payload):
            try handleUpdateComponents(payload)
        case .updateDataModel(let payload):
            try handleUpdateDataModel(payload)
        case .deleteSurface:
            handleDeleteSurface()
        }
    }

    // MARK: - Action subscription

    /// Subscribe to actions dispatched from components on this surface.
    /// Returns a `Subscription` token — keep it alive for as long as you want to receive events.

